package com.antra.payment; import java.math.*; import java.util.*; import org.springframework.http.*; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/payments") class PaymentController {private final Repo repo;private final KafkaTemplate<String,Object> kafka;PaymentController(Repo r,KafkaTemplate<String,Object> k){repo=r;kafka=k;} @PostMapping ResponseEntity<Payment> pay(Authentication a,@RequestParam Long reservationId,@RequestParam BigDecimal amount){if(repo.findByReservationId(reservationId).isPresent())return ResponseEntity.status(409).build();Payment p=repo.save(new Payment(reservationId,a.getName(),amount));kafka.send("payment-completed",reservationId.toString(),Map.of("reservationId",reservationId,"username",a.getName(),"amount",amount));return ResponseEntity.status(201).body(p);}@GetMapping("/{reservationId}") Payment status(@PathVariable Long reservationId,Authentication a){Payment p=repo.findByReservationId(reservationId).orElseThrow();if(!p.username.equals(a.getName()))throw new org.springframework.web.server.ResponseStatusException(HttpStatus.FORBIDDEN);return p;} interface Repo extends org.springframework.data.jpa.repository.JpaRepository<Payment,Long>{Optional<Payment> findByReservationId(Long id);}}
